package ui.generated;

import base.BaseTest;
import org.openqa.selenium.support.ui.ExpectedConditions;
import org.openqa.selenium.support.ui.WebDriverWait;
import org.testng.Assert;
import org.testng.annotations.Test;
import pages.generated.SauceDemoLoginPageBody;
import utils.ConfigReader;

import java.time.Duration;

// Logs in to SauceDemo using ONLY the page object generated by Pipeline A.
// No locator in this test was typed by hand.
public class SauceDemoGeneratedLoginTest extends BaseTest {

    @Test(description = "Login with the generated page object")
    public void loginWithGeneratedPageObject() {
        driver.get(ConfigReader.get("loginUrl"));

        SauceDemoLoginPageBody loginPage = new SauceDemoLoginPageBody(driver);
        loginPage.typeUsername(ConfigReader.get("valid.username"));
        loginPage.typePassword(ConfigReader.get("valid.password"));
        loginPage.clickLoginButton();

        new WebDriverWait(driver, Duration.ofSeconds(10))
                .until(ExpectedConditions.urlContains(ConfigReader.get("inventory.url")));
        Assert.assertTrue(driver.getCurrentUrl().contains("inventory.html"),
                "Login with the generated page object did not reach the inventory page");
    }
}